import json
import math
from pathlib import Path
from pyscipopt import Model, quicksum

DATA_PATH = "/root/data.json"
OUT_PATH = "/root/report.json"

data = json.loads(Path(DATA_PATH).read_text())

vehicle_count = int(data["vehicle_count"])
vehicle_capacity = float(data["vehicle_capacity"])
penalty_weight = float(data["penalty_weight"])
depot = data["depot"]
stations_data = data["stations"]

n = len(stations_data)
station_ids = [int(s["id"]) for s in stations_data]
if len(station_ids) != len(set(station_ids)):
    raise ValueError("duplicate station ids")

idx_to_id = {idx: sid for idx, sid in enumerate(station_ids)}

targets = [float(s["net_rebalancing_target"]) for s in stations_data]
initial_bikes = [float(s["initial_bikes"]) for s in stations_data]
station_capacity = [float(s["station_capacity"]) for s in stations_data]


def great_circle_miles(a, b, radius=3960.0):
    lat1 = float(a["latitude"])
    lon1 = float(a["longitude"])
    lat2 = float(b["latitude"])
    lon2 = float(b["longitude"])

    deg_to_rad = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg_to_rad
    phi2 = (90.0 - lat2) * deg_to_rad
    theta1 = lon1 * deg_to_rad
    theta2 = lon2 * deg_to_rad

    cos_arc = (
        math.sin(phi1) * math.sin(phi2) * math.cos(theta1 - theta2)
        + math.cos(phi1) * math.cos(phi2)
    )
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius


STATIONS = list(range(n))
START = "START"
END = "END"


def node_loc(node):
    if node in (START, END):
        return depot
    return stations_data[node]


# distance lookup between all node pairs we need (station-station, depot-station)
dist = {}
for i in STATIONS:
    for j in STATIONS:
        if i != j:
            dist[(i, j)] = great_circle_miles(node_loc(i), node_loc(j))
depot_dist = {i: great_circle_miles(depot, node_loc(i)) for i in STATIONS}

VEHICLES = list(range(vehicle_count))
Q = vehicle_capacity
BIGM = Q + 1.0

model = Model("bike_rebalancing")
model.hideOutput()

# arc variables per vehicle: START->i, i->j (i!=j stations), i->END
x_start = {}
x_end = {}
x_arc = {}
for k in VEHICLES:
    for i in STATIONS:
        x_start[k, i] = model.addVar(vtype="B", name=f"xs_{k}_{i}")
        x_end[k, i] = model.addVar(vtype="B", name=f"xe_{k}_{i}")
    for i in STATIONS:
        for j in STATIONS:
            if i != j:
                x_arc[k, i, j] = model.addVar(vtype="B", name=f"x_{k}_{i}_{j}")

visit = {}
for k in VEHICLES:
    for i in STATIONS:
        visit[k, i] = model.addVar(vtype="B", name=f"visit_{k}_{i}")

pick = {}
drop = {}
pickup_flag = {}
for k in VEHICLES:
    for i in STATIONS:
        pick[k, i] = model.addVar(vtype="I", lb=0, ub=Q, name=f"pick_{k}_{i}")
        drop[k, i] = model.addVar(vtype="I", lb=0, ub=Q, name=f"drop_{k}_{i}")
        pickup_flag[k, i] = model.addVar(vtype="B", name=f"pf_{k}_{i}")

start_load = {k: model.addVar(vtype="I", lb=0, ub=Q, name=f"start_load_{k}") for k in VEHICLES}
end_load = {k: model.addVar(vtype="I", lb=0, ub=Q, name=f"end_load_{k}") for k in VEHICLES}
load = {}
for k in VEHICLES:
    for i in STATIONS:
        load[k, i] = model.addVar(vtype="I", lb=0, ub=Q, name=f"load_{k}_{i}")

# MTZ order variables
order = {}
for k in VEHICLES:
    for i in STATIONS:
        order[k, i] = model.addVar(vtype="C", lb=1, ub=n, name=f"order_{k}_{i}")

# routing constraints
for k in VEHICLES:
    model.addCons(quicksum(x_start[k, i] for i in STATIONS) == 1)
    model.addCons(quicksum(x_end[k, i] for i in STATIONS) == 1)
    # each vehicle must visit at least one station -- implied by above but keep explicit
    model.addCons(quicksum(visit[k, i] for i in STATIONS) >= 1)

    for i in STATIONS:
        incoming = x_start[k, i] + quicksum(x_arc[k, j, i] for j in STATIONS if j != i)
        outgoing = x_end[k, i] + quicksum(x_arc[k, i, j] for j in STATIONS if j != i)
        model.addCons(incoming == visit[k, i])
        model.addCons(outgoing == visit[k, i])
        model.addCons(x_start[k, i] <= visit[k, i])
        model.addCons(x_end[k, i] <= visit[k, i])

# a station visited by at most... rule: vehicle visits a station no more than once (already 0/1 per vehicle)
# no restriction that only one vehicle may visit a station; but pick/drop applies per vehicle stop

# MTZ subtour elimination (per vehicle)
for k in VEHICLES:
    for i in STATIONS:
        for j in STATIONS:
            if i != j:
                model.addCons(order[k, i] - order[k, j] + n * x_arc[k, i, j] <= n - 1)

# pickup/dropoff linked to visit, mutual exclusivity per stop
for k in VEHICLES:
    for i in STATIONS:
        model.addCons(pick[k, i] <= Q * pickup_flag[k, i])
        model.addCons(drop[k, i] <= Q * (visit[k, i] - pickup_flag[k, i]))
        model.addCons(pickup_flag[k, i] <= visit[k, i])

# load consistency
for k in VEHICLES:
    for i in STATIONS:
        model.addCons(
            load[k, i] >= start_load[k] + pick[k, i] - drop[k, i] - BIGM * (1 - x_start[k, i])
        )
        model.addCons(
            load[k, i] <= start_load[k] + pick[k, i] - drop[k, i] + BIGM * (1 - x_start[k, i])
        )
        for j in STATIONS:
            if i != j:
                model.addCons(
                    load[k, j] >= load[k, i] + pick[k, j] - drop[k, j] - BIGM * (1 - x_arc[k, i, j])
                )
                model.addCons(
                    load[k, j] <= load[k, i] + pick[k, j] - drop[k, j] + BIGM * (1 - x_arc[k, i, j])
                )
        model.addCons(end_load[k] >= load[k, i] - BIGM * (1 - x_end[k, i]))
        model.addCons(end_load[k] <= load[k, i] + BIGM * (1 - x_end[k, i]))
    # if vehicle visits nothing... not allowed (>=1 station), so end_load always tied to some visited station

# station-level aggregates
total_pick = {}
total_drop = {}
net_change = {}
dev_pos = {}
dev_neg = {}
for i in STATIONS:
    total_pick[i] = quicksum(pick[k, i] for k in VEHICLES)
    total_drop[i] = quicksum(drop[k, i] for k in VEHICLES)
    net_change[i] = total_pick[i] - total_drop[i]
    dev_pos[i] = model.addVar(vtype="C", lb=0, name=f"devp_{i}")
    dev_neg[i] = model.addVar(vtype="C", lb=0, name=f"devn_{i}")
    model.addCons(net_change[i] - targets[i] == dev_pos[i] - dev_neg[i])

    # station capacity constraint on final inventory
    final_inv = initial_bikes[i] - total_pick[i] + total_drop[i]
    model.addCons(final_inv >= 0)
    model.addCons(final_inv <= station_capacity[i])

travel_distance = quicksum(
    depot_dist[i] * (x_start[k, i] + x_end[k, i]) for k in VEHICLES for i in STATIONS
) + quicksum(
    dist[i, j] * x_arc[k, i, j] for k in VEHICLES for i in STATIONS for j in STATIONS if i != j
)

unmet_penalty = penalty_weight * quicksum(dev_pos[i] + dev_neg[i] for i in STATIONS)

model.setObjective(travel_distance + unmet_penalty, "minimize")

model.setParam("limits/time", 300.0)
model.setParam("limits/gap", 0.0)

for name in [
    "randomization/randomseedshift",
    "randomization/permutationseed",
    "randomization/lpseed",
]:
    try:
        model.setParam(name, 0)
    except Exception:
        pass
try:
    model.setParam("parallel/maxnthreads", 1)
except Exception:
    pass

model.optimize()

status = str(model.getStatus()).lower()
if model.getNSols() == 0:
    raise RuntimeError(f"SCIP found no feasible solution; status={status}")

print("status:", status)
print("objective:", model.getObjVal())

# extract solution
sol = {}
sol["status"] = status
sol["objective"] = model.getObjVal()

vehicles_out = []
for k in VEHICLES:
    # reconstruct route
    # find start station
    start_i = None
    for i in STATIONS:
        if model.getVal(x_start[k, i]) > 0.5:
            start_i = i
            break
    route_idx = [start_i]
    cur = start_i
    visited_set = {start_i}
    while True:
        nxt = None
        if model.getVal(x_end[k, cur]) > 0.5:
            nxt = END
        else:
            for j in STATIONS:
                if j != cur and model.getVal(x_arc[k, cur, j]) > 0.5:
                    nxt = j
                    break
        if nxt == END or nxt is None:
            break
        route_idx.append(nxt)
        cur = nxt

    route_ids = ["depot_start"] + [idx_to_id[i] for i in route_idx] + ["depot_end"]

    stops = []
    for i in route_idx:
        p = round(model.getVal(pick[k, i]))
        d = round(model.getVal(drop[k, i]))
        l = round(model.getVal(load[k, i]))
        stops.append(
            {
                "station_id": idx_to_id[i],
                "bikes_picked_up": float(p),
                "bikes_dropped_off": float(d),
                "load_after_stop": float(l),
            }
        )

    sl = round(model.getVal(start_load[k]))
    el = round(model.getVal(end_load[k]))

    vehicles_out.append(
        {
            "vehicle_id": k + 1,
            "start_load": float(sl),
            "route": route_ids,
            "stops": stops,
            "end_load": float(el),
        }
    )

stations_out = []
for i in STATIONS:
    tp = round(sum(model.getVal(pick[k, i]) for k in VEHICLES))
    td = round(sum(model.getVal(drop[k, i]) for k in VEHICLES))
    net = tp - td
    unmet = abs(targets[i] - net)
    stations_out.append(
        {
            "station_id": idx_to_id[i],
            "net_rebalancing_target": float(targets[i]),
            "total_bikes_picked_up": float(tp),
            "total_bikes_dropped_off": float(td),
            "net_bike_change": float(net),
            "unmet_rebalancing_amount": float(unmet),
        }
    )

# recompute travel distance and penalty independently
recomputed_distance = 0.0
for veh in vehicles_out:
    route = veh["route"]
    for a, b in zip(route[:-1], route[1:]):
        if a == "depot_start":
            loc_a = depot
        elif a == "depot_end":
            loc_a = depot
        else:
            loc_a = node_loc(station_ids.index(a))
        if b == "depot_start":
            loc_b = depot
        elif b == "depot_end":
            loc_b = depot
        else:
            loc_b = node_loc(station_ids.index(b))
        recomputed_distance += great_circle_miles(loc_a, loc_b)

total_unmet = sum(s["unmet_rebalancing_amount"] for s in stations_out)
unmet_penalty_val = penalty_weight * total_unmet
objective_val = recomputed_distance + unmet_penalty_val

report = {
    "summary": {
        "objective": objective_val,
        "travel_distance_miles": recomputed_distance,
        "unmet_rebalancing_penalty": unmet_penalty_val,
        "total_unmet_rebalancing_amount": total_unmet,
    },
    "vehicles": vehicles_out,
    "stations": stations_out,
}

Path(OUT_PATH).write_text(json.dumps(report, indent=2))
print("recomputed_distance:", recomputed_distance)
print("total_unmet:", total_unmet)
print("objective_val:", objective_val)
print("model objective:", model.getObjVal())
